PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?z ?zn WHERE {
  ?ahu a brick:AirHandlingUnit ; rdfs:label "AHU02" .
  ?ahu brick:hasPart ?zone .
  ?zone a brick:Zone .
  OPTIONAL { ?zone rdfs:label ?zl }
  BIND(COALESCE(STR(?zone), ?zl) AS ?zn)
  BIND(?zone AS ?z)
}

